fn numpy_append(arr: Vec<f32>, values: Vec<f32>) -> Vec<f32> {
    // Pre-allocate a new vector with capacity to hold all elements from both input vectors.
    let mut result = Vec::with_capacity(arr.len() + values.len());
    
    // Extend the result vector by all elements from the first vector.
    result.extend_from_slice(&arr);
    
    // Extend the result vector by all elements from the second vector.
    result.extend_from_slice(&values);
    
    // The result now contains arr followed by values, preserving order.
    result
}